class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        operation, condition_part = current_hint.split(' ', 1)
        cond = self.parse_condition(condition_part)

        rows = len(current_grid)
        cols = len(current_grid[0]) if rows > 0 else 0
        valid_cells = []

        for r in range(1, rows + 1):
            for c in range(1, cols + 1):
                if current_grid[r-1][c-1] != 0:
                    continue
                if operation == 'sum':
                    op_value = r + c
                elif operation == 'product':
                    op_value = r * c
                elif operation == 'difference':
                    op_value = r - c
                else:
                    continue

                valid = False
                if cond[0] == 'less_than':
                    valid = op_value < cond[1]
                elif cond[0] == 'greater_than':
                    valid = op_value > cond[1]
                elif cond[0] == 'contains_digit':
                    valid = str(cond[1]) in str(op_value)
                elif cond[0] == 'even':
                    valid = op_value % 2 == 0
                elif cond[0] == 'odd':
                    valid = op_value % 2 == 1
                elif cond[0] == 'between':
                    valid = cond[1] <= op_value <= cond[2]
                if valid:
                    valid_cells.append((r, c))

        for (r, c) in valid_cells:
            new_grid = [row.copy() for row in current_grid]
            new_grid[r-1][c-1] = player_idx
            if self.has_won(new_grid, player_idx):
                return self.prepare_response((r, c), message)

        if not valid_cells:
            position_selected = (1, 1)
        else:
            max_row, max_col = rows, cols
            scored_cells = []
            for (r, c) in valid_cells:
                if player_idx == 1:
                    min_dist = min(c-1, max_col - c)
                    edge_score = max_col - min_dist
                else:
                    min_dist = min(r-1, max_row - r)
                    edge_score = max_row - min_dist

                adjacent = 0
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 1 <= nr <= max_row and 1 <= nc <= max_col and current_grid[nr-1][nc-1] == player_idx:
                            adjacent += 1
                total = edge_score + adjacent *5
                scored_cells.append((-total, -edge_score, -adjacent, r, c))

            scored_cells.sort()
            (_, _, _, r, c) = scored_cells[0] if scored_cells else (0,0,0,1,1)
            position_selected = (r, c)

        return self.prepare_response(position_selected, message)

    def parse_condition(self, condition_part):
        if condition_part.startswith('is less than '):
            return ('less_than', int(condition_part.split('is less than ')[1]))
        elif condition_part.startswith('is greater than '):
            return ('greater_than', int(condition_part.split('is greater than ')[1]))
        elif condition_part.startswith('contains digit '):
            return ('contains_digit', int(condition_part.split('contains digit ')[1]))
        elif condition_part == 'is even':
            return ('even',)
        elif condition_part == 'is odd':
            return ('odd',)
        elif 'is between ' in condition_part and 'inclusive' in condition_part:
            parts = condition_part.split()
            return ('between', int(parts[2]), int(parts[4]))
        else:
            raise ValueError('Invalid condition')

    def has_won(self, grid, player):
        rows, cols = len(grid), len(grid[0]) if grid else 0
        visited = set()
        q = deque()

        if player == 1:
            for r in range(rows):
                if grid[r][0] == player:
                    q.append((r, 0))
                    visited.add((r, 0))
            target = cols -1
        else:
            for c in range(cols):
                if grid[0][c] == player:
                    q.append((0, c))
                    visited.add((0, c))
            target = rows -1

        while q:
            r, c = q.popleft()
            if (player == 1 and c == target) or (player ==2 and r == target):
                return True
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    nr, nc = r+dr, c+dc
                    if 0<=nr<rows and 0<=nc<cols and grid[nr][nc] == player and (nr,nc) not in visited:
                        visited.add((nr,nc))
                        q.append((nr,nc))
        return False

    def prepare_response(self, position, message):
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position, type='custom')]
        )

