        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        # Parse hint
        hint_parts = current_hint.split()
        operation = hint_parts[0]
        condition_rest = ' '.join(hint_parts[1:])

        cond_type = None
        v1 = None
        v2 = None

        if condition_rest.startswith('is less than'):
            cond_type = 'less_than'
            v1 = int(condition_rest.split()[-1])
        elif condition_rest.startswith('is greater than'):
            cond_type = 'greater_than'
            v1 = int(condition_rest.split()[-1])
        elif condition_rest.startswith('contains digit'):
            cond_type = 'contains_digit'
            v1 = int(condition_rest.split()[-1])
        elif condition_rest == 'is even':
            cond_type = 'even'
        elif condition_rest == 'is odd':
            cond_type = 'odd'
        elif condition_rest.startswith('is between'):
            parts = condition_rest.split()
            v1 = int(parts[2])
            v2 = int(parts[4].replace(',', ''))
            cond_type = 'between_inclusive'

        # Generate valid positions
        valid_positions = []
        rows = len(current_grid)
        cols = len(current_grid[0]) if rows else 0

        for r in range(rows):
            for c in range(cols):
                if current_grid[r][c] == 0:
                    row_1 = r + 1
                    col_1 = c + 1

                    if operation == 'sum':
                        val = row_1 + col_1
                    elif operation == 'product':
                        val = row_1 * col_1
                    elif operation == 'difference':
                        val = row_1 - col_1

                    valid = False
                    if cond_type == 'less_than':
                        valid = val < v1
                    elif cond_type == 'greater_than':
                        valid = val > v1
                    elif cond_type == 'contains_digit':
                        valid = str(v1) in str(val)
                    elif cond_type == 'even':
                        valid = val % 2 == 0
                    elif cond_type == 'odd':
                        valid = val % 2 != 0
                    elif cond_type == 'between_inclusive':
                        valid = v1 <= val <= v2

                    if valid:
                        valid_positions.append((row_1, col_1))

        # Check winning moves
        for pos in valid_positions:
            row_1, col_1 = pos
            code_r, code_c = row_1 - 1, col_1 - 1
            temp_grid = [row.copy() for row in current_grid]
            temp_grid[code_r][code_c] = player_idx

            if player_idx == 1:
                start = [(r, 0) for r in range(len(temp_grid)) if temp_grid[r][0] == 1]
                target_col = len(temp_grid[0]) - 1
            else:
                start = [(0, c) for c in range(len(temp_grid[0])) if temp_grid[0][c] == 2]
                target_row = len(temp_grid) - 1

            visited = set(start)
            queue = deque(start)
            found = False

            while queue:
                r, c = queue.popleft()
                if (player_idx == 1 and c == target_col) or (player_idx == 2 and r == target_row):
                    found = True
                    break
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < len(temp_grid) and 0 <= nc < len(temp_grid[0]):
                            if temp_grid[nr][nc] == player_idx and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

            if found:
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=(row_1, col_1), type='custom')]
                )

        # Heuristic selection
        max_score = -1
        best_pos = None
        for pos in valid_positions:
            row_1, col_1 = pos
            code_r, code_c = row_1 - 1, col_1 - 1
            adjacent = 0

            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = code_r + dr, code_c + dc
                    if 0 <= nr < len(current_grid) and 0 <= nc < len(current_grid[0]):
                        if current_grid[nr][nc] == player_idx:
                            adjacent += 1

            edge = col_1 if player_idx == 1 else row_1
            score = adjacent * 1000 + edge

            if score > max_score or (score == max_score and (best_pos is None or pos < best_pos)):
                max_score = score
                best_pos = pos

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=best_pos, type='custom')]
        )

