        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def parse_hint(self, current_hint):
        parts = current_hint.split()
        operation = parts[0]
        condition = ' '.join(parts[1:])

        condition_type = None
        v1 = None
        v2 = None

        if condition.startswith('is less than '):
            condition_type = 'less_than'
            v1 = int(condition.split()[-1])
        elif condition.startswith('is greater than '):
            condition_type = 'greater_than'
            v1 = int(condition.split()[-1])
        elif condition.startswith('contains digit '):
            condition_type = 'contains_digit'
            v1 = int(condition.split()[-1])
        elif condition == 'is even':
            condition_type = 'even'
        elif condition == 'is odd':
            condition_type = 'odd'
        elif 'is between' in condition:
            m = re.match(r'is between (\d+) and (\d+), inclusive', condition)
            if m:
                condition_type = 'between_inclusive'
                v1 = int(m.group(1))
                v2 = int(m.group(2))
            else:
                raise ValueError(f"Invalid between condition: {condition}")
        else:
            raise ValueError(f"Unknown condition: {condition}")

        return operation, condition_type, v1, v2

