        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        # Parse the hint into operation and condition
        operation, condition_part = current_hint.split(' ', 1)
        condition_type = None
        params = []

        # Determine condition type and parameters
        match_less = re.fullmatch(r'is less than (\d+)', condition_part)
        if match_less:
            condition_type = 'less_than'
            params = [int(match_less.group(1))]
        else:
            match_greater = re.fullmatch(r'is greater than (\d+)', condition_part)
            if match_greater:
                condition_type = 'greater_than'
                params = [int(match_greater.group(1))]
            else:
                match_contains = re.fullmatch(r'contains digit (\d)', condition_part)
                if match_contains:
                    condition_type = 'contains_digit'
                    params = [int(match_contains.group(1))]
                elif condition_part == 'is even':
                    condition_type = 'even'
                elif condition_part == 'is odd':
                    condition_type = 'odd'
                else:
                    match_between = re.fullmatch(r'is between (\d+) and (\d+) inclusive', condition_part)
                    if match_between:
                        condition_type = 'between'
                        params = [int(match_between.group(1)), int(match_between.group(2))]

        num_rows = len(current_grid)
        num_cols = len(current_grid[0]) if num_rows > 0 else 0
        valid_cells = []

        for i in range(num_rows):
            for j in range(num_cols):
                if current_grid[i][j] != 0:
                    continue
                row_idx = i + 1
                col_idx = j + 1

                # Compute operation value
                if operation == 'sum':
                    val = row_idx + col_idx
                elif operation == 'product':
                    val = row_idx * col_idx
                elif operation == 'difference':
                    val = row_idx - col_idx
                else:
                    continue

                # Check condition
                valid = False
                if condition_type == 'less_than':
                    valid = val < params[0]
                elif condition_type == 'greater_than':
                    valid = val > params[0]
                elif condition_type == 'contains_digit':
                    valid = str(params[0]) in str(val)
                elif condition_type == 'even':
                    valid = val % 2 == 0
                elif condition_type == 'odd':
                    valid = val % 2 != 0
                elif condition_type == 'between':
                    valid = params[0] <= val <= params[1]

                if not valid:
                    continue

                # Edge priority
                if player_idx == 1:
                    edge_priority = 1 if (col_idx == 1 or col_idx == num_cols) else 0
                else:
                    edge_priority = 1 if (row_idx == 1 or row_idx == num_rows) else 0

                # Adjacent count
                adjacent_count = 0
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < num_rows and 0 <= nj < num_cols and current_grid[ni][nj] == player_idx:
                            adjacent_count += 1

                # Min distance
                if player_idx == 1:
                    min_dist = min(col_idx - 1, num_cols - col_idx)
                else:
                    min_dist = min(row_idx - 1, num_rows - row_idx)

                valid_cells.append( (-edge_priority, -adjacent_count, min_dist, row_idx, col_idx) )

        # Select best cell
        position_selected = (0, 0)
        if valid_cells:
            valid_cells.sort()
            best = valid_cells[0]
            position_selected = (best[3], best[4])

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

