            if operation == 'sum':
                return r + c
            elif operation == 'product':
                return r * c
            elif operation == 'difference':
                return r - c
            else:
                raise ValueError("Invalid operation")

        def parse_hint(hint_str):
            parts = hint_str.split()
            operation = parts[0]
            cond_parts = parts[1:]
            cond_type = None
            params = None
            if cond_parts[0] == 'is':
                if cond_parts[1] == 'less' and cond_parts[2] == 'than':
                    cond_type = 'less_than'
                    params = int(cond_parts[3])
                elif cond_parts[1] == 'greater' and cond_parts[2] == 'than':
                    cond_type = 'greater_than'
                    params = int(cond_parts[3])
                elif cond_parts[1] == 'between':
                    cond_type = 'between'
                    v1 = int(cond_parts[2])
                    v2 = int(cond_parts[4].rstrip(','))
                    params = (v1, v2)
                elif cond_parts[1] == 'even':
                    cond_type = 'even'
                elif cond_parts[1] == 'odd':
                    cond_type = 'odd'
                else:
                    raise ValueError("Unknown condition")
            elif cond_parts[0] == 'contains':
                cond_type = 'contains_digit'
                params = int(cond_parts[2])
            else:
                raise ValueError("Unknown condition")
            return operation, (cond_type, params)

        operation, (cond_type, params) = parse_hint(current_hint)

        rows = len(current_grid)
        cols = len(current_grid[0]) if rows > 0 else 0
        valid_cells = []
        for r in range(1, rows + 1):
            for c in range(1, cols + 1):
                if current_grid[r-1][c-1] != 0:
                    continue
                value = compute_operation(r, c, operation)
                valid = False
                if cond_type == 'less_than':
                    valid = value < params
                elif cond_type == 'greater_than':
                    valid = value > params
                elif cond_type == 'contains_digit':
                    valid = str(params) in str(abs(value))
                elif cond_type == 'even':
                    valid = value % 2 == 0
                elif cond_type == 'odd':
                    valid = value % 2 != 0
                elif cond_type == 'between':
                    v1, v2 = params
                    valid = v1 <= value <= v2
                if valid:
                    valid_cells.append((r, c))

        winning_cells = []
        for cell in valid_cells:
            r, c = cell
            sim_grid = [row.copy() for row in current_grid]
            sim_grid[r-1][c-1] = player_idx
            if player_idx == 1:
                left_edge = [(i, 0) for i in range(rows) if sim_grid[i][0] == 1]
