                                if 0 <= nx < rows and 0 <= ny < cols and sim_grid[nx][ny] == 1:
                                    stack.append((nx, ny))
                if winning_cells:
                    break
            else:
                top_edge = [(0, j) for j in range(cols) if sim_grid[0][j] == 2]
                visited = set()
                for (i, j) in top_edge:
                    stack = [(i, j)]
                    while stack:
                        x, y = stack.pop()
                        if x == rows - 1:
                            winning_cells.append(cell)
                            break
                        if (x, y) in visited:
                            continue
                        visited.add((x, y))
                        for dx in [-1, 0, 1]:
                            for dy in [-1, 0, 1]:
                                if dx == 0 and dy == 0:
                                    continue
                                nx = x + dx
                                ny = y + dy
                                if 0 <= nx < rows and 0 <= ny < cols and sim_grid[nx][ny] == 2:
                                    stack.append((nx, ny))
                if winning_cells:
                    break

        if winning_cells:
            position_selected = winning_cells[0]
        else:
            adjacency_counts = {}
            for (r, c) in valid_cells:
                count = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 1 <= nr <= rows and 1 <= nc <= cols:
                            if current_grid[nr-1][nc-1] == player_idx:
                                count += 1
                adjacency_counts[(r, c)] = count

            if player_idx == 1:
                valid_cells.sort(key=lambda x: (-x[1], -adjacency_counts[x], x[0]))
